/* Generated by Vite. Cache contains only an explicit list of public static resources. */
const CACHE_NAME = 'nexo-public-__CACHE_VERSION__';
const PUBLIC_ASSETS = new Set(__PUBLIC_ASSETS__);
const CACHE_PREFIX = 'nexo-public-';

function publicResource(request) {
 const url = new URL(request.url);
 return request.method === 'GET' && request.mode !== 'navigate' && url.origin === self.location.origin && !url.search && !url.hash && PUBLIC_ASSETS.has(url.pathname);
}

function acceptable(response, path) {
 if (!response.ok || response.redirected || response.type === 'opaque' || /(?:no-store|private)/i.test(response.headers.get('Cache-Control') || '')) return false;
 const type = response.headers.get('Content-Type') || '';
 if (/\.js$/.test(path)) return /(?:javascript|ecmascript)/i.test(type);
 if (/\.css$/.test(path)) return /text\/css/i.test(type);
 if (/\.woff2?$/.test(path)) return /(?:font\/|application\/(?:font|octet-stream))/i.test(type);
 if (/\.(?:png|jpe?g|svg|webp|avif)$/.test(path)) return /image\//i.test(type);
 if (path === '/manifest.webmanifest') return /(?:manifest\+json|application\/json)/i.test(type);
 return path === '/offline.html' && /text\/html/i.test(type);
}

// Never skipWaiting or claim open tabs. The next release activates only once all
// existing app windows have closed, preserving in-progress check-in and forms.
self.addEventListener('install', event => {
 event.waitUntil((async () => {
  const cache = await caches.open(CACHE_NAME);
  try {
   await Promise.all([...PUBLIC_ASSETS].map(async path => {
    const request = new Request(new URL(path, self.location.origin), { credentials: 'omit', cache: 'reload', redirect: 'error' });
    const response = await fetch(request);
    if (!acceptable(response, path)) throw new Error('Public resource unavailable');
    await cache.put(request, response);
   }));
  } catch (error) {
   await caches.delete(CACHE_NAME);
   throw error;
  }
 })());
});

self.addEventListener('activate', event => {
 event.waitUntil((async () => {
  const keys = await caches.keys();
  await Promise.all(keys.filter(key => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME).map(key => caches.delete(key)));
 })());
});

self.addEventListener('fetch', event => {
 const request = event.request;
 if (request.method !== 'GET') return;
 if (request.mode === 'navigate') {
  // No HTML documents are persisted, including administrative/ticket routes.
  event.respondWith(fetch(request).catch(async () => {
   const cache = await caches.open(CACHE_NAME);
   const fallback = await cache.match('/offline.html');
   return new Response(fallback ? await fallback.text() : 'Sem conexão. O credenciamento exige internet.', { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
  }));
  return;
 }
 if (!publicResource(request)) return;
 event.respondWith((async () => {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  if (cached) return cached;
  // Do not persist runtime responses: installation is the only cache writer.
  return fetch(new Request(request, { credentials: 'omit', redirect: 'error' }));
 })());
});
